/**
 * The port's contract: SAME INPUTS, SAME OUTPUTS as the Python it came from.
 *
 * The fixtures (`fixtures/scoreParity.json`) were generated by RUNNING
 * phunk-client's own `score()` — the function copied verbatim into
 * `fixtures/gen-score-parity.py` (MIT, © Ramitphi,
 * https://github.com/Ramitphi/phunk-client) — over hand cases that pin each
 * rule the card names, plus 60 seeded random graphs. A diff here means the
 * TypeScript port diverged from the Python, not that the fixture is wrong.
 */

import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import { describe, expect, it } from 'vitest';

import {
  CHANNEL_POINTS,
  channelNameFor,
  type ReasonName,
  scoreSuggestions,
  suggestionReason,
} from '~/snapchain/nodeApi/recommend';

interface ParityCase {
  id: string;
  me: number;
  following: number[];
  theirFollows: Record<string, number[]>;
  channelAuthors: Record<string, Record<string, number>>;
  kwargs: {
    min_followed_by?: number;
    exclude?: number[];
    limit?: number;
  };
  expected: {
    fid: number;
    score: number;
    followedBy: number[];
    channels: string[];
  }[];
}

const cases: ParityCase[] = JSON.parse(
  readFileSync(join(__dirname, 'fixtures', 'scoreParity.json'), 'utf8'),
) as ParityCase[];

const runCase = (testCase: ParityCase) =>
  scoreSuggestions(
    testCase.me,
    new Set(testCase.following),
    new Map(
      Object.entries(testCase.theirFollows).map(([fid, targets]) => [
        Number(fid),
        new Set(targets),
      ]),
    ),
    new Map(
      Object.entries(testCase.channelAuthors).map(([url, authors]) => [
        url,
        new Map(
          Object.entries(authors).map(([fid, count]) => [Number(fid), count]),
        ),
      ]),
    ),
    {
      ...(testCase.kwargs.min_followed_by !== undefined
        ? { minFollowedBy: testCase.kwargs.min_followed_by }
        : {}),
      ...(testCase.kwargs.exclude
        ? { exclude: new Set(testCase.kwargs.exclude) }
        : {}),
      ...(testCase.kwargs.limit !== undefined
        ? { limit: testCase.kwargs.limit }
        : {}),
    },
  );

describe('scoreSuggestions (ported 1:1 from phunk recommend.py)', () => {
  it('matches the Python output on every fixture case', () => {
    expect(cases.length).toBeGreaterThanOrEqual(70);
    for (const testCase of cases) {
      const got = runCase(testCase).map((suggestion) => ({
        fid: suggestion.fid,
        score: suggestion.score,
        followedBy: suggestion.followedBy,
        channels: suggestion.channels,
      }));
      expect(got, `case ${testCase.id}`).toEqual(testCase.expected);
    }
  });

  it('drops a single-mutual candidate (min_followed_by)', () => {
    const out = scoreSuggestions(
      1,
      new Set([2]),
      new Map([[2, new Set([3])]]),
      new Map(),
    );
    expect(out).toEqual([]);
  });

  it('keeps a single-mutual candidate when a channel is shared', () => {
    const out = scoreSuggestions(
      1,
      new Set([2]),
      new Map([[2, new Set([3])]]),
      new Map([['https://warpcast.com/~/channel/dev', new Map([[3, 4]])]]),
    );
    expect(out.map((suggestion) => suggestion.fid)).toEqual([3]);
    expect(out[0]?.score).toBe(1 + CHANNEL_POINTS);
  });

  it('never suggests someone the viewer already follows, or the viewer', () => {
    const out = scoreSuggestions(
      1,
      new Set([2, 3]),
      new Map([
        [2, new Set([1, 3, 4])],
        [3, new Set([1, 2, 4])],
      ]),
      new Map(),
    );
    expect(out.map((suggestion) => suggestion.fid)).toEqual([4]);
  });

  it('breaks ties by mutuals, then channel posts, then the older account', () => {
    // Same score, different mutual counts: two mutuals beat none.
    const byMutuals = scoreSuggestions(
      1,
      new Set([2, 3]),
      new Map([
        [2, new Set([4])],
        [3, new Set([4])],
      ]),
      new Map([['https://warpcast.com/~/channel/x', new Map([[5, 1]])]]),
    );
    expect(byMutuals.map((suggestion) => suggestion.fid)).toEqual([4, 5]);

    // Same score and mutuals: more channel posts first.
    const byPosts = scoreSuggestions(
      1,
      new Set([2, 3]),
      new Map([
        [2, new Set([4])],
        [3, new Set([5])],
      ]),
      new Map([
        [
          'https://warpcast.com/~/channel/x',
          new Map([
            [4, 1],
            [5, 7],
          ]),
        ],
      ]),
    );
    expect(byPosts.map((suggestion) => suggestion.fid)).toEqual([5, 4]);

    // Everything equal: the older account (lower fid) first.
    const byAge = scoreSuggestions(
      1,
      new Set([2, 3]),
      new Map([
        [2, new Set([41, 40])],
        [3, new Set([40, 41])],
      ]),
      new Map(),
    );
    expect(byAge.map((suggestion) => suggestion.fid)).toEqual([40, 41]);
  });
});

describe('channelNameFor', () => {
  it('turns both channel URL spellings into a #key', () => {
    expect(channelNameFor('https://warpcast.com/~/channel/dev')).toBe('#dev');
    expect(channelNameFor('https://farcaster.xyz/~/channel/founders')).toBe(
      '#founders',
    );
  });

  it('keeps an unknown chain:// URL as it is', () => {
    expect(channelNameFor('chain://eip155:7777777/erc721:0xabc')).toBe(
      'chain://eip155:7777777/erc721:0xabc',
    );
  });
});

describe('suggestionReason', () => {
  const names = (entries: [number, string][]): Map<number, ReasonName> =>
    new Map(entries.map(([fid, username]) => [fid, { fid, username }]));

  it("spells one mutual in phunk's words", () => {
    expect(
      suggestionReason(
        { followedBy: [7], channels: [] },
        names([[7, 'alice']]),
      ),
    ).toBe('Followed by @alice, whom you follow');
  });

  it('spells two mutuals', () => {
    expect(
      suggestionReason(
        { followedBy: [7, 8], channels: [] },
        names([
          [7, 'alice'],
          [8, 'bob'],
        ]),
      ),
    ).toBe('Followed by @alice and @bob you follow');
  });

  it('caps the names at three and counts the rest', () => {
    expect(
      suggestionReason(
        { followedBy: [7, 8, 9, 10, 11], channels: [] },
        names([
          [7, 'alice'],
          [8, 'bob'],
          [9, 'carol'],
          [10, 'dave'],
          [11, 'erin'],
        ]),
      ),
    ).toBe('Followed by @alice, @bob, @carol and 2 more you follow');
  });

  it("says the channel in phunk's words when there are no mutuals", () => {
    expect(
      suggestionReason(
        {
          followedBy: [],
          channels: ['https://warpcast.com/~/channel/dev'],
        },
        new Map(),
      ),
    ).toBe('posts in #dev, a channel you read');
  });

  it('joins both halves of the reason with a middle dot', () => {
    expect(
      suggestionReason(
        {
          followedBy: [7],
          channels: ['https://warpcast.com/~/channel/dev'],
        },
        names([[7, 'alice']]),
      ),
    ).toBe(
      'Followed by @alice, whom you follow · posts in #dev, a channel you read',
    );
  });

  it('never invents a handle: an unresolved fid reads as its fid', () => {
    expect(
      suggestionReason({ followedBy: [99], channels: [] }, new Map()),
    ).toBe('Followed by fid 99, whom you follow');
  });
});
